// CONFIG: settings come from the Setup Form. Collections come from the "collections" Data Table.
const defaults = {
  inboxId: '',                 // collection_id bookmarks are read from (Setup Form)
  fallbackId: '',              // collection_id for bookmarks the LLM can't place (Setup Form)
  confidenceThreshold: 0.7,    // below this, the bookmark goes to the fallback
  extraRules: '',              // optional extra instructions for the LLM (Setup Form)
  telegramChatId: '',
  llmProvider: 'ollama',       // 'ollama' or 'openai'
  llmUrl: 'http://ollama:11434/api/chat',
  llmModel: 'qwen3:8b',
};
const settings = { ...defaults, ...($getWorkflowStaticData('global').config || {}) };
if (!settings.inboxId || !settings.fallbackId) {
  throw new Error('Run the Setup Form first: Inbox ID and Fallback ID are required');
}
const collections = $('Get Collections').all().map(i => i.json)
  .filter(r => r.collection_id !== undefined && r.collection_id !== null && r.collection_id !== '')
  .map(r => ({ id: Number(r.collection_id), name: String(r.name || ''), description: String(r.description || '') }));
const ids = collections.map(c => String(c.id));
if (!ids.includes(String(settings.inboxId))) throw new Error(`Inbox ID ${settings.inboxId} is not a collection_id in the collections table`);
if (!ids.includes(String(settings.fallbackId))) throw new Error(`Fallback ID ${settings.fallbackId} is not a collection_id in the collections table`);
if (String(settings.inboxId) === String(settings.fallbackId)) throw new Error('Inbox ID and Fallback ID must differ, or sorted bookmarks would loop');
return [{ json: { ...settings, collections } }];

const cfg = $('Config').first().json;
const list = cfg.collections.map(c => `${c.id} ${c.name}: ${c.description}`).join('\n');

const SYSTEM = `You sort bookmarks into collections. Reply with ONE JSON object and nothing else. No prose, no markdown fences.

# Input
You receive: title, url, description/excerpt (may be empty).

# Collections (pick exactly one id)
${list}

Never output any other id. If several fit, pick the most specific one.
If none fits well, use the fallback collection ${cfg.fallbackId} and give a low confidence.
${cfg.extraRules ? '\n' + cfg.extraRules + '\n' : ''}
# Output shape
{"collection_id": number, "confidence": number between 0 and 1, "reason": "short reason"}`;

const item = $json;
const user = `Title: ${item.title || ''}\nURL: ${item.link || ''}\nDescription: ${item.excerpt || item.note || ''}`;
const messages = [
  { role: 'system', content: SYSTEM },
  { role: 'user', content: user },
];
const body = cfg.llmProvider === 'openai'
  ? { model: cfg.llmModel, messages, response_format: { type: 'json_object' } }
  : { model: cfg.llmModel, stream: false, format: 'json', messages };

return { json: {
  id: item._id,
  title: item.title || '',
  allowed: cfg.collections.map(c => Number(c.id)),
  fallback: Number(cfg.fallbackId),
  threshold: Number(cfg.confidenceThreshold),
  provider: cfg.llmProvider,
  url: cfg.llmUrl,
  body,
} };

const src = $('Build Input').item.json;
const reply = $input.first().json;
const text = src.provider === 'openai' ? reply.choices?.[0]?.message?.content : reply.message?.content;
let out = {};
try { out = JSON.parse(text); } catch (e) {}
let id = Number(out.collection_id);
const conf = Number(out.confidence) || 0;
const confident = src.allowed.includes(id) && conf >= src.threshold;
if (!confident) id = src.fallback;
return { json: {
  id: src.id,
  title: src.title,
  collection: id,
  confidence: conf,
  reason: out.reason || (confident ? '' : 'low confidence or no valid collection'),
  confident,
} };
